"use client";

import { FeatureCard as OriginalFeatureCard } from "@/components/marketing/feature-card";

import { getProjectPreview } from "@/lib/projects/project-preview";

import { getFallbackHomeWorkSections } from "@/lib/sanity/fallback-projects";

import { withPlaygroundProps } from "@/components/design-system/playground-context"

const FeatureCard = withPlaygroundProps(OriginalFeatureCard, "FeatureCard")

export function FeatureCardDemo() {
    const { recentProjects } = getFallbackHomeWorkSections();
    const project = recentProjects[0];
    if (!project)
        return null;
    return (<div className="w-full max-w-xl rounded-lg border border-border bg-background p-4">
      <FeatureCard title={project.title} description={project.description} slug={project.slug} previewSrc={getProjectPreview(project).src} previewAlt={getProjectPreview(project).alt}/>
    </div>);
}

export default FeatureCardDemo
